package sourceprofile

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"net"
	"net/netip"
	"sort"
	"strconv"
	"strings"

	wire "hoopa/protocol/sourcecontrol"
)

// Project produces the independent expectation from validated generated bytes.
// It never obtains an expected value from a running core. The core projects its
// actual native objects separately. Results contain no live probe selection.
func Project(raw []byte, generation string) (wire.Snapshot, error) {
	c, err := Validate(raw, generation)
	if err != nil {
		return wire.Snapshot{}, err
	}
	s := wire.Snapshot{SchemaVersion: 2, ConfigSHA256: digest(raw), Controller: c.Controller, Entries: []wire.Entry{}, Proxies: []wire.Proxy{}, Rules: []wire.Rule{}}
	for _, e := range c.Listeners {
		users, err := json.Marshal(e.Users)
		if err != nil {
			return wire.Snapshot{}, ErrProfile
		}
		s.Entries = append(s.Entries, wire.Entry{Name: e.Name, Type: e.Type, Address: net.JoinHostPort(e.Listen, strconv.Itoa(int(e.Port))), AuthSHA256: digest(users)})
	}
	for name, kind := range map[string]string{"DIRECT": "Direct", "REJECT": "Reject", "REJECT-DROP": "RejectDrop", "COMPATIBLE": "Compatible", "PASS": "Pass"} {
		s.Proxies = append(s.Proxies, wire.Proxy{Name: name, Type: kind, Members: []string{}})
	}
	members := []string{"DIRECT", "REJECT"}
	types := map[string]string{"direct": "Direct", "http": "Http", "socks5": "Socks5", "ss": "Shadowsocks", "trojan": "Trojan", "vmess": "Vmess", "vless": "Vless", "hysteria2": "Hysteria2"}
	for _, n := range c.Proxies {
		name := n["name"].(string)
		kind := n["type"].(string)
		x := wire.Proxy{Name: name, Type: types[kind], Members: []string{}}
		if kind != "direct" {
			x.Address = net.JoinHostPort(n["server"].(string), n["port"].(json.Number).String())
		}
		s.Proxies = append(s.Proxies, x)
		members = append(members, name)
	}
	for _, g := range c.Groups {
		x := wire.Proxy{Name: g.Name, Type: "Selector", Members: append([]string{}, g.Proxies...), Selected: g.Proxies[0]}
		if g.Type == "url-test" {
			x.Type = "URLTest"
			x.Selected = ""
			p := g.Probe()
			x.Probe = &p
		}
		s.Proxies = append(s.Proxies, x)
		members = append(members, g.Name)
	}
	s.Proxies = append(s.Proxies, wire.Proxy{Name: "GLOBAL", Type: "Selector", Members: members, Selected: "DIRECT"})
	for _, r := range c.Rules {
		parts := strings.Split(r, ",")
		if parts[0] == "MATCH" {
			s.Rules = append(s.Rules, wire.Rule{Type: "Match", Target: parts[1]})
			continue
		}
		if parts[0] == "AND" {
			end := strings.LastIndex(r, ")),")
			body := r[len("AND,(("):end]
			payloads := []string{}
			for _, atom := range strings.Split(body, "),(") {
				a := projectAtom(strings.Split(atom, ","))
				payloads = append(payloads, "("+a.Type+","+a.Payload+")")
			}
			s.Rules = append(s.Rules, wire.Rule{Type: "AND", Payload: "(" + strings.Join(payloads, " && ") + ")", Target: r[end+3:]})
			continue
		}
		x := projectAtom(parts)
		x.Target = parts[2]
		s.Rules = append(s.Rules, x)
	}
	sort.Slice(s.Entries, func(i, j int) bool { return s.Entries[i].Name < s.Entries[j].Name })
	sort.Slice(s.Proxies, func(i, j int) bool { return s.Proxies[i].Name < s.Proxies[j].Name })
	if s.Validate() != nil {
		return wire.Snapshot{}, ErrProfile
	}
	return s, nil
}

func projectAtom(parts []string) wire.Rule {
	x := wire.Rule{Payload: parts[1]}
	switch parts[0] {
	case "DOMAIN":
		x.Type = "Domain"
		x.Payload = strings.ToLower(parts[1])
	case "DOMAIN-SUFFIX":
		x.Type = "DomainSuffix"
		x.Payload = strings.ToLower(parts[1])
	case "IN-NAME":
		x.Type = "InName"
	case "IP-CIDR":
		x.Type = "IPCIDR"
		prefix, _ := netip.ParsePrefix(parts[1])
		x.Payload = prefix.String()
	}
	return x
}
func digest(raw []byte) string { h := sha256.Sum256(raw); return hex.EncodeToString(h[:]) }
